6// A class to create and add nodes
7template <typename T>
8class TreeNode {
9public:
10
11    TreeNode(T val): data(val) {}
12        
13    void add_child(vector<TreeNode<T>*> child_arr) {
14        children = child_arr;
15    }
16
17    T data;
18    vector<TreeNode<T>*> children;
19};
