21// A class to create tree and perform tree operations
22template <typename T>
23class Tree {
24public:
25
26    Tree(TreeNode<T>* root_node): root(root_node) {}
27
28    TreeNode<T>* root {nullptr};
29};
30
31int main() {
32
33    // Create the root node
34    TreeNode<string>* root = new TreeNode<string>("Book");
35
36    // Create children of root
37    TreeNode<string>* child1 = new TreeNode<string>("1");
38    TreeNode<string>* child2 = new TreeNode<string>("2");
39    TreeNode<string>* child3 = new TreeNode<string>("3");
40
41    // Create leaf nodes
