48    TreeNode<string>* child3_2 = new TreeNode<string>("3.2");
49    TreeNode<string>* child3_3 = new TreeNode<string>("3.3");
50
51    // Describe relationships between the nodes
52    // and add children to the root node
53    root->add_child({child1, child2, child3});
54
55    // Add children to child1
56    child1->add_child({child1_1, child1_2, child1_3, child1_4});
57
58    // Add children to child2
59    child2->add_child({child2_1});
60
61    // Add children to child3
62    child3->add_child({child3_1, child3_2, child3_3});
63
64    // Create the tree
65    Tree<string> general_tree = Tree<string>(root);
66
67    return 0;
